"use client";
/**
 * EosRoutinesApp: the app's Routines screen as a template. The app shell's sidebar (the workspace switcher, the Home
 * and Activity control, the nav with Routines chosen, the projects and the chats) beside the Routines page: its header,
 * the Installed and Discover control, and either the routines already running or the recommended pick and the new
 * routines to add. EosRoutinesPage is the page on its own, for an app shell of your own.
 *
 * It follows the five Eos looks (`look`) in light or dark (`mode`, dark by default: the Eos app is charcoal). Pastel
 * is the plain app; night sets the apps on small frosted tiles and the pick on a deep, dim grain gradient; editorial
 * sets the page in the big serif with hairline rows; glass floats the app as frosted glass on the look's gradient;
 * bold sets a heavy grotesque and puts the pick on a vivid field.
 *
 * Motion (motion.ts): the sidebar's selection and both controls slide on the shared indicator; the cards rise in, on
 * load and whenever Installed or Discover is chosen; rows and cards answer hover with a lift or a wash and press with
 * a small settle. Every word is a prop; the defaults are Morrow's.
 *
 * Inspired by rico (@_heyrico)'s twin visual vibe.
 */
import { RiFlashlightLine } from "@remixicon/react";
import { useState, type CSSProperties, type ReactNode } from "react";
import { EosAppShell, type EosAppShellProps } from "./app-shell";
import { EosAppGlyph, type EosAppKind } from "./glyphs";
import { eosMotion, eosRiseStyle } from "./motion";
import { EosSegmentedControl } from "./segmented-control";
import { cx, useControlled } from "./shared";
import { EosTheme, useEosTheme } from "./theme";
import type { EosLook, EosMode } from "./tokens";

/** A routine as the Routines page lists it. */
export interface EosRoutineItem {
  id: string;
  title: string;
  /** One line on what it does. */
  text: string;
  /** The apps it uses; the first two show before its title. */
  apps?: readonly EosAppKind[];
  /** When it runs, shown on a running routine. */
  schedule?: string;
  /** Who makes it, shown on a new one. */
  maker?: string;
  /** Where the card leads; the whole card becomes the link. */
  href?: string;
}

export interface EosRoutinesContent {
  /** The page's title, also the app's top bar and the control's name. */
  title: string;
  subline: string;
  /** The two views, on the control and over their lists. */
  installed: string;
  discover: string;
  /** The routines already running, under Installed. */
  running: readonly EosRoutineItem[];
  /** The pick at the top of Discover, by an app. */
  recommended: { heading: string; title: string; text: string; by: string; app: EosAppKind; href?: string };
  /** The heading over the new routines, and the routines. */
  more: string;
  fresh: readonly EosRoutineItem[];
}

export type EosRoutinesSegment = "installed" | "discover";

/** Morrow's Routines page. */
export const EOS_ROUTINES_CONTENT: EosRoutinesContent = {
  title: "Routines",
  subline: "Run the work you repeat",
  installed: "Installed",
  discover: "Discover",
  running: [
    { id: "morning-brief", title: "Morning brief", text: "Calendar, inbox and weather in one note at 7:00.", apps: ["calendar", "mail", "notes"], schedule: "Every day at 7:00", href: "#morning-brief" },
    { id: "invoice-nudge", title: "Invoice nudge", text: "Chases unpaid invoices kindly after 14 days.", apps: ["books", "mail"], schedule: "Daily, once an invoice is 14 days late", href: "#invoice-nudge" },
    { id: "standup-digest", title: "Standup digest", text: "Yesterday's updates in one post.", apps: ["chat", "docs", "tasks"], schedule: "Weekdays at 9:30", href: "#standup-digest" },
  ],
  recommended: {
    heading: "Recommended",
    title: "Weekly cash summary",
    text: "Adds up last week's paid invoices every Monday and posts the total in #finance.",
    by: "Coffer",
    app: "books",
    href: "#cash-summary",
  },
  more: "New routines",
  fresh: [
    { id: "lead-scout", title: "Lead scout", text: "New leads in your niche, added to your sheet.", apps: ["mail", "sheet"], maker: "Pinecrest", href: "#lead-scout" },
    { id: "release-notes", title: "Release notes", text: "Merged changes turned into a changelog draft.", apps: ["tasks", "docs"], maker: "Kettle", href: "#release-notes" },
  ],
};

const CSS = `
.eos-routines{box-sizing:border-box;width:100%;max-width:820px;margin:0 auto;padding:clamp(28px,6vw,64px) clamp(18px,5vw,40px) 56px;color:var(--eos-text)}
.eos-routines-title{margin:0;font-size:clamp(26px,4vw,32px);font-weight:550;letter-spacing:-.02em;color:var(--eos-text)}
.eos-routines-sub{margin:8px 0 26px;font-size:17px;color:var(--eos-text-secondary)}
.eos-routines-h{margin:44px 0 14px;font-size:17px;font-weight:500;color:var(--eos-text-secondary)}
.eos-rlist{display:grid;gap:14px;margin:0;padding:0;list-style:none}
.eos-rcard{position:relative;display:grid;gap:10px;padding:20px 22px;border-radius:20px;border:1px solid var(--eos-hairline);background:var(--eos-card);-webkit-backdrop-filter:blur(var(--eos-card-blur));backdrop-filter:blur(var(--eos-card-blur));transition:transform var(--eos-dur-hover) var(--eos-ease)}
.eos-rcard::before,.eos-rcard::after{content:"";position:absolute;inset:-1px;border-radius:inherit;opacity:0;pointer-events:none;transition:opacity var(--eos-dur-hover) var(--eos-ease)}
.eos-rcard::before{box-shadow:var(--eos-lift-shadow)}
.eos-rcard::after{z-index:2;border:1px solid var(--eos-hairline-strong)}
@media (hover:hover){
  .eos-rcard[data-open=true]:hover{transform:translateY(var(--eos-lift-sm))}
  .eos-rcard[data-open=true]:hover::before,.eos-rcard[data-open=true]:hover::after{opacity:1}
  .eos-rcard[data-open=true]:hover:active{transform:translateY(var(--eos-lift-sm)) scale(var(--eos-press))}
}
.eos-rcard[data-open=true]:active{transform:scale(var(--eos-press));transition-duration:var(--eos-dur-press)}
.eos-rcard:has(.eos-rcard-link:focus-visible){outline:2px solid var(--eos-focus);outline-offset:3px}
.eos-rcard-top{display:flex;align-items:center;gap:12px}
.eos-rcard-glyphs{display:inline-flex;gap:4px;flex:none}
.eos-rcard-title{margin:0;font-size:17px;font-weight:500;color:var(--eos-text)}
.eos-rcard-link{color:inherit;text-decoration:none;-webkit-tap-highlight-color:transparent}
.eos-rcard-link::after{content:"";position:absolute;inset:0;z-index:1;border-radius:inherit}
.eos-rcard-link:focus-visible{outline:none}
.eos-rcard-text{margin:0;font-size:15.5px;line-height:1.55;color:var(--eos-text-secondary)}
.eos-rcard-by{display:flex;align-items:center;gap:8px;margin:6px 0 0;font-size:15px;color:var(--eos-text-tertiary)}
.eos-rcard-by b{font-weight:450;color:var(--eos-text)}
.eos-rcard-when{margin-left:auto;font-size:14px;color:var(--eos-text-tertiary);white-space:nowrap}
@media (max-width:520px){.eos-rcard-top{flex-wrap:wrap}.eos-rcard-when{margin-left:0;width:100%}}
[data-eos-look=editorial] .eos-routines{max-width:760px;padding-top:clamp(36px,7vw,88px)}
[data-eos-look=editorial] .eos-routines-title{font-family:var(--eos-font-display);font-weight:var(--eos-display-weight);font-size:clamp(40px,6vw,64px);line-height:1;letter-spacing:var(--eos-display-tracking)}
[data-eos-look=editorial] .eos-routines-sub{margin:14px 0 34px;font-size:18px}
[data-eos-look=editorial] .eos-routines-h{margin:60px 0 4px;padding-bottom:14px;border-bottom:1px solid var(--eos-hairline);font-family:var(--eos-font-display);font-size:24px;font-weight:400;letter-spacing:-.01em;color:var(--eos-text)}
[data-eos-look=editorial] .eos-rlist{gap:0}
[data-eos-look=editorial] .eos-rcard{padding:22px 4px;border-width:0 0 1px;border-radius:0;background:none;-webkit-backdrop-filter:none;backdrop-filter:none}
[data-eos-look=editorial] .eos-rcard::before{inset:0 -14px;border-radius:14px;box-shadow:none;background:var(--eos-hover)}
[data-eos-look=editorial] .eos-rcard::after{display:none}
[data-eos-look=editorial] .eos-rcard[data-open=true]:hover{transform:none}
[data-eos-look=editorial] .eos-rcard[data-open=true]:hover:active,[data-eos-look=editorial] .eos-rcard[data-open=true]:active{transform:scale(var(--eos-press))}
[data-eos-look=editorial] .eos-rcard-title{font-size:19px}
[data-eos-look=bold] .eos-routines-title{font-family:var(--eos-font-display);font-weight:var(--eos-display-weight);font-size:clamp(34px,5vw,54px);line-height:.96;letter-spacing:var(--eos-display-tracking)}
[data-eos-look=bold] .eos-routines-h{font-weight:650;color:var(--eos-text)}
[data-eos-look=bold] .eos-rcard{border-radius:var(--eos-radius-card)}
[data-eos-look=bold] .eos-rcard[data-pick=true]{isolation:isolate;min-height:180px;align-content:end;border-color:transparent;background:var(--eos-gradient-orchid);color:var(--eos-ink-orchid)}
:is([data-eos-look=bold],[data-eos-look=night]) .eos-rcard[data-pick=true]>.eos-rcard-grain{position:absolute;inset:0;z-index:-1;border-radius:inherit;pointer-events:none;background-image:var(--eos-grain);background-size:200px 200px;mix-blend-mode:overlay;opacity:var(--eos-grain-opacity)}
[data-eos-look=bold] .eos-rcard[data-pick=true] .eos-rcard-title{font-family:var(--eos-font-display);font-size:26px;font-weight:700;letter-spacing:-.02em;color:inherit}
[data-eos-look=bold] .eos-rcard[data-pick=true] .eos-rcard-text,[data-eos-look=bold] .eos-rcard[data-pick=true] .eos-rcard-by,[data-eos-look=bold] .eos-rcard[data-pick=true] .eos-rcard-by b{color:var(--eos-ink-soft-orchid)}
[data-eos-look=night] .eos-rcard-glyphs{gap:6px}
[data-eos-look=night] .eos-rcard-glyphs>svg{box-sizing:content-box;padding:6px;border-radius:10px;background:var(--eos-frost);box-shadow:inset 0 0 0 1px var(--eos-frost-rim)}
[data-eos-look=night] .eos-rcard[data-pick=true]{isolation:isolate;border-color:transparent;background:var(--eos-gradient-dawn);color:var(--eos-ink-dawn)}
[data-eos-look=night] .eos-rcard[data-pick=true] .eos-rcard-title{color:inherit}
[data-eos-look=night] .eos-rcard[data-pick=true] .eos-rcard-text,[data-eos-look=night] .eos-rcard[data-pick=true] .eos-rcard-by,[data-eos-look=night] .eos-rcard[data-pick=true] .eos-rcard-by b{color:var(--eos-ink-soft-dawn)}
.eos-rcard-grain{display:none}
:is([data-eos-look=bold],[data-eos-look=night]) .eos-rcard[data-pick=true]>.eos-rcard-grain{display:block}
.eos-rapp{box-sizing:border-box;height:var(--eos-rapp-h,100vh);overflow:hidden}
.eos-rapp-window{width:100%}
@media (min-width:900px){
  .eos-rapp[data-eos-look=glass]{padding:clamp(16px,2.6vw,36px)}
  .eos-rapp[data-eos-look=glass] .eos-rapp-window{border-radius:22px;border:1px solid rgba(255,255,255,.14);box-shadow:0 40px 90px -40px rgba(20,14,70,.65)}
}
`;

function Glyphs({ apps }: { apps?: readonly EosAppKind[] }) {
  if (!apps?.length) return null;
  return (
    <span className="eos-rcard-glyphs" aria-hidden>
      {apps.slice(0, 2).map((app) => (
        <EosAppGlyph key={app} app={app} size={20} />
      ))}
    </span>
  );
}

/** A card's title: the link the whole card becomes when it leads somewhere, plain text otherwise. */
function Title({ text, href }: { text: string; href?: string }) {
  return (
    <p className="eos-rcard-title">
      {href ? (
        <a className="eos-rcard-link" href={href}>
          {text}
        </a>
      ) : (
        text
      )}
    </p>
  );
}

export interface EosRoutinesPageProps {
  /** Any part of the copy and the routines, over Morrow's. */
  content?: Partial<EosRoutinesContent>;
  segment?: EosRoutinesSegment;
  defaultSegment?: EosRoutinesSegment;
  onSegmentChange?: (segment: EosRoutinesSegment) => void;
  headingLevel?: 1 | 2 | 3;
  className?: string;
  style?: CSSProperties;
}

/** The Routines page on its own: its header, the Installed and Discover control, and the routines in each. */
export function EosRoutinesPage({ content, segment, defaultSegment = "discover", onSegmentChange, headingLevel = 2, className, style }: EosRoutinesPageProps) {
  const c: EosRoutinesContent = { ...EOS_ROUTINES_CONTENT, ...content };
  const [view, setView] = useControlled<EosRoutinesSegment>(segment, defaultSegment, onSegmentChange);
  // The page rises in on load, header first; after that each view mounts anew when chosen and its cards rise at once.
  const [chosen, setChosen] = useState(false);
  const motion = eosMotion(useEosTheme()?.look);
  const Title1 = `h${headingLevel}` as "h2";
  const Sub = `h${Math.min(headingLevel + 1, 4)}` as "h3";
  const head = (index: number, extra?: string) => ({ className: cx(extra, "eos-rise"), style: eosRiseStyle(index, motion) });
  let place = chosen ? 0 : 3;
  const rise = (extra?: string) => head(place++, extra);
  const card = (r: EosRoutineItem, extra?: ReactNode) => (
    <li key={r.id} {...rise("eos-rcard")} data-open={Boolean(r.href)}>
      <div className="eos-rcard-top">
        <Glyphs apps={r.apps} />
        <Title text={r.title} href={r.href} />
        {r.schedule && <span className="eos-rcard-when">{r.schedule}</span>}
      </div>
      <p className="eos-rcard-text">{r.text}</p>
      {extra}
    </li>
  );
  return (
    <div className={cx("eos-routines", className)} style={style}>
      <style>{CSS}</style>
      <Title1 {...head(0, "eos-routines-title")}>{c.title}</Title1>
      <p {...head(1, "eos-routines-sub")}>{c.subline}</p>
      <div {...head(2)}>
        <EosSegmentedControl
          segments={[
            { value: "installed", label: c.installed },
            { value: "discover", label: c.discover },
          ]}
          value={view}
          onChange={(next) => {
            setChosen(true);
            setView(next === "installed" ? "installed" : "discover");
          }}
          label={c.title}
        />
      </div>
      {view === "installed" ? (
        <div key="installed">
          <Sub {...rise("eos-routines-h")}>{c.installed}</Sub>
          <ul className="eos-rlist">{c.running.map((r) => card(r))}</ul>
        </div>
      ) : (
        <div key="discover">
          <Sub {...rise("eos-routines-h")}>{c.recommended.heading}</Sub>
          <ul className="eos-rlist">
            <li {...rise("eos-rcard")} data-open={Boolean(c.recommended.href)} data-pick>
              <span className="eos-rcard-grain" aria-hidden />
              <div className="eos-rcard-top">
                <RiFlashlightLine size={20} aria-hidden />
                <Title text={c.recommended.title} href={c.recommended.href} />
              </div>
              <p className="eos-rcard-text">{c.recommended.text}</p>
              <p className="eos-rcard-by">
                by <EosAppGlyph app={c.recommended.app} size={18} /> <b>{c.recommended.by}</b>
              </p>
            </li>
          </ul>
          <Sub {...rise("eos-routines-h")}>{c.more}</Sub>
          <ul className="eos-rlist">
            {c.fresh.map((r) =>
              card(
                r,
                r.maker ? (
                  <p className="eos-rcard-by">
                    by <b>{r.maker}</b>
                  </p>
                ) : null,
              ),
            )}
          </ul>
        </div>
      )}
    </div>
  );
}

export interface EosRoutinesAppProps extends Omit<EosAppShellProps, "children" | "mode" | "title" | "height" | "className" | "style"> {
  /** One of the five Eos looks. */
  look?: EosLook;
  /** Light or dark; dark by default, as the Eos app is charcoal. */
  mode?: EosMode;
  /** Any part of the page's copy and routines, over Morrow's. */
  content?: Partial<EosRoutinesContent>;
  segment?: EosRoutinesSegment;
  defaultSegment?: EosRoutinesSegment;
  onSegmentChange?: (segment: EosRoutinesSegment) => void;
  /** The app's height; the whole window by default. */
  height?: number | string;
  className?: string;
  style?: CSSProperties;
}

/** The Routines screen: the app shell with Routines chosen in its sidebar, and the Routines page beside it. */
export function EosRoutinesApp({
  look = "pastel",
  mode = "dark",
  content,
  segment,
  defaultSegment,
  onSegmentChange,
  height = "100vh",
  defaultActive = "routines",
  className,
  style,
  ...shell
}: EosRoutinesAppProps) {
  const title = content?.title ?? EOS_ROUTINES_CONTENT.title;
  return (
    <EosTheme
      look={look}
      mode={mode}
      className={cx("eos-rapp", className)}
      style={{ "--eos-rapp-h": typeof height === "number" ? `${height}px` : height, ...style } as CSSProperties}
    >
      <EosAppShell {...shell} defaultActive={defaultActive} className="eos-rapp-window" mode={mode} height="100%" title={title}>
        <EosRoutinesPage content={content} segment={segment} defaultSegment={defaultSegment} onSegmentChange={onSegmentChange} />
      </EosAppShell>
    </EosTheme>
  );
}

// @zeus-internal
/** Small helpers the Eos pieces share. */
import { useCallback, useEffect, useLayoutEffect, useState } from "react";

export const cx = (...parts: (string | false | null | undefined)[]) => parts.filter(Boolean).join(" ");

export const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** A value that is controlled when `value` is given and owned here otherwise. */
export function useControlled<T>(value: T | undefined, initial: T, onChange?: (next: T) => void) {
  const [own, setOwn] = useState(initial);
  const current = value === undefined ? own : value;
  const set = useCallback(
    (next: T) => {
      if (value === undefined) setOwn(next);
      onChange?.(next);
    },
    [value, onChange],
  );
  return [current, set] as const;
}

/**
 * Whether a media query matches. The server and the first render use `initial`, so markup hydrates; the real answer
 * follows once mounted, and changes as the window does.
 */
export function useMedia(query: string, initial = false): boolean {
  const [matches, setMatches] = useState(initial);
  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const list = window.matchMedia(query);
    const update = () => setMatches(list.matches);
    update();
    list.addEventListener?.("change", update);
    return () => list.removeEventListener?.("change", update);
  }, [query]);
  return matches;
}

/** The index a roving-focus key moves to, or -1 for a key the group ignores. */
export function rovingIndex(key: string, index: number, count: number): number {
  if (count === 0) return -1;
  if (key === "ArrowRight" || key === "ArrowDown") return (index + 1) % count;
  if (key === "ArrowLeft" || key === "ArrowUp") return (index - 1 + count) % count;
  if (key === "Home") return 0;
  if (key === "End") return count - 1;
  return -1;
}

/** Visually hidden text for assistive technology. */
export const SR_ONLY_CSS =
  ".eos-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}";
